<?php
$root=dirname(__DIR__);$failures=[];$assert=function(bool $condition,string $message)use(&$failures):void{if(!$condition)$failures[]=$message;};
$guard=file_get_contents($root.'/services/PasskeySignatureGuard.php');$options=file_get_contents($root.'/request/passkey_signature_options.php');$verify=file_get_contents($root.'/request/passkey_signature_verify.php');$payroll=file_get_contents($root.'/services/RhPayrollWorkflowService.php');$validation=file_get_contents($root.'/rh/validation_paie_rh.php');$requestPdf=file_get_contents($root.'/request/export_demande_rh_fiche_pdf.php');$requestService=file_get_contents($root.'/services/RhLegalRequestService.php');$requestPad=file_get_contents($root.'/js/rh_explanation_signature_pad.js');$company=file_get_contents($root.'/services/RhCompanyProfileService.php');$companyLink=file_get_contents($root.'/services/RhEmployeeContractCompanyService.php');$bank=file_get_contents($root.'/services/RhPersonnelBankService.php');$contractRepo=file_get_contents($root.'/modules/payroll/repositories/EmployeeContractRepository.php');$preset=file_get_contents($root.'/services/RhEmployeeContractClausePresetService.php');$contractPage=file_get_contents($root.'/rh/contrats_employes_rh.php');$contractPdf=file_get_contents($root.'/rh/export_contrat_employe_pdf.php');$clauseJs=file_get_contents($root.'/rh/assets/employee-contract-default-clauses.js');$transferPdf=file_get_contents($root.'/rh/export_bulletins_paie_pdf.php');$leave=file_get_contents($root.'/rh/conges_initialisation_rh.php');$financeJs=file_get_contents($root.'/contrats/assets/workflow-finance-schedule.js');$passkeyJs=file_get_contents($root.'/js/passkeys.js');
$assert(str_contains($guard,"unset(\$_SESSION['passkey_signature_proof'])"),'La preuve Passkey doit rester à usage unique.');
$assert(str_contains($guard,'hash_equals($expectedContext, $proofContext)'),'Le garde Passkey doit lier une preuve à un contexte.');
$assert(str_contains($options,"'context' => \$context"),'Le challenge de signature doit mémoriser son contexte.');
$assert(str_contains($verify,"'credential_id' => (int)\$row['id']"),'La preuve doit tracer la Passkey utilisée.');
$assert(str_contains($passkeyJs,'deriveSignatureContext'),'Les anciens formulaires doivent recevoir un contexte dérivé.');
$assert(str_contains($requestService,"'rh_request:' . \$id . ':' . \$signatureRole"),'La signature d’une demande RH doit être liée à la demande et au rôle.');
$assert(str_contains($requestPad,'form.dataset.passkeyContext = `rh_request:${requestId}:${role}`'),'Le formulaire de demande RH doit envoyer le même contexte Passkey.');
$assert(str_contains($payroll,"'rh_payroll:'.\$period.':'.\$role"),'Le visa paie doit être lié à la période et au rôle.');
$assert(str_contains($payroll,'rh_payroll_distribution_log'),'La diffusion paie doit être idempotente.');
$assert(str_contains($payroll,"'code'=>'missing_bank'"),'Les coordonnées bancaires manquantes doivent bloquer la paie.');
$assert(str_contains($payroll,"'severity'=>'blocking','code'=>'missing_contract'"),'Un contrat salarié absent doit bloquer la validation.');
$assert(str_contains($payroll,'NOT IN (2,3)')&&str_contains($payroll,"<> 'prestataire'"),'La paie doit exclure prestataires et consultants.');
$assert(str_contains($validation,"\$_SESSION['rh_payroll_csrf']")&&str_contains($validation,'hash_equals($csrf'),'Les actions de paie doivent être protégées par CSRF.');
$assert(str_contains($validation,'data-passkey-context="rh_payroll:'),'L’interface paie doit fournir un contexte Passkey explicite.');
$assert(str_contains($requestPdf,"'Circuit d’approbation et signatures'"),'Le PDF RH doit afficher son circuit.');
$assert(!str_contains($requestPdf,"'>Champ<'"),'Le PDF RH ne doit plus être un export Champ/Valeur.');
$assert(str_contains($company,'rh_company_profiles'),'Les fiches entreprises doivent être persistées.');
$assert(str_contains($company,"'legal_name' => 'FIDEST'")&&str_contains($company,'CI-ABJ-2017-B-20163'),'FIDEST doit être créée automatiquement sans duplication.');
$assert(str_contains($companyLink,'company_snapshot_json')&&str_contains($companyLink,'snapshot_at'),'Le contrat doit figer un snapshot entreprise.');
$assert(str_contains($contractPage,'company_profile_id')&&str_contains($contractPage,'RhEmployeeContractCompanyService'),'Le contrat salarié doit permettre de choisir l’entreprise.');
$assert(str_contains($contractPage,'employee_contract:')&&str_contains($contractPage,'data-passkey-context'),'Les signatures du contrat doivent être contextualisées.');
$assert(str_contains($preset,"'CDD'")&&str_contains($preset,"'STAGE'")&&str_contains($preset,"'CDI'"),'Les clauses par défaut doivent varier selon le type de contrat.');
$assert(str_contains($preset,'Article 1 — Textes régissant le contrat')&&str_contains($preset,'Article 14 — Rupture et fin du CDD'),'Le modèle CDD doit reprendre la structure complète du contrat RH de référence.');
$assert(str_contains($clauseJs,'Charger les clauses par défaut')&&str_contains($clauseJs,'isBlankOrLegacy'),'L’éditeur doit proposer les clauses complètes et migrer les anciens cinq modèles génériques.');
$assert(str_contains($contractRepo,'RhEmployeeContractClausePresetService::forType'),'Un contrat sans clauses saisies doit recevoir les clauses modifiables de son type.');
$assert(str_contains($contractRepo,'assertEmployee')&&str_contains($contractRepo,'NOT IN (2,3)'),'Le repository de contrat doit refuser prestataires et consultants.');
$assert(str_contains($contractPdf,'SIGNATURES ET TRAÇABILITÉ')&&str_contains($contractPdf,'RhEmployeeContractCompanyService'),'Le PDF du contrat doit résoudre l’entreprise figée et afficher la traçabilité.');
$assert(str_contains($contractPdf,'save_to_dossier')&&str_contains($contractPdf,"==='1'"),'La prévisualisation ne doit pas archiver le contrat sans demande explicite.');
$assert(str_contains($contractPdf,'generated_document_path')&&str_contains($contractPdf,'signed_document_path'),'Le PDF contrat doit rester archivable explicitement dans le dossier RH.');
$assert(str_contains($contractPdf,'user_devis_banamur')&&str_contains($contractPdf,'signature'),'Le PDF final doit pouvoir afficher les signatures professionnelles.');
$assert(str_contains($bank,'rh_personnel_bank_accounts')&&str_contains($bank,'assertEmployee'),'Les coordonnées bancaires doivent avoir un service sécurisé salarié.');
$assert(str_contains($transferPdf,'Compte / IBAN')&&str_contains($transferPdf,'bank_account_number'),'L’ordre de virement doit contenir les données bancaires individuelles.');
$assert(str_contains($leave,'prestataire')&&str_contains($leave,'NOT IN (2, 3)'),'Les soldes de congés doivent exclure les prestataires.');
$assert(!str_contains($financeJs,'Conditions de décaissement par rubrique du planning'),'Le panneau d’échéances retiré ne doit pas réapparaître.');
if($failures){foreach($failures as$failure)fwrite(STDERR,"[FAIL] $failure\n");exit(1);}echo "RH workflow security tests: OK\n";
